//! The D3D11 leaves game adapters link through ReScaleFrame::Graphics: state snapshots and
//! binding restores, texture descriptions and dumps, constant-buffer reads and the frame tap. The Runtime
//! uses the same modules through its rlib dependency, so adapters do not link the Runtime archive.

/// C bindings this crate sees: its private frame-tap header (generated by build.rs) with the public
/// SDK headers from rsf-game-sys, plus the D3D11 texture records. The Runtime's sys re-exports this
/// module.
#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    clippy::all
)]
pub mod sys {
    pub use crate::d3d11_output_platform::{
        RSF_D3D11_BIND_RENDER_TARGET, RSF_D3D11_BIND_SHADER_RESOURCE,
        RSF_D3D11_FORMAT_R11G11B10_FLOAT, RSF_D3D11_FORMAT_R32_FLOAT, RSF_D3D11_FORMAT_RG16_FLOAT,
        RSF_D3D11_FORMAT_RG32_FLOAT, RSF_D3D11_FORMAT_RGBA16_FLOAT, RSF_D3D11_FORMAT_RGBA32_FLOAT,
        RSF_D3D11_USAGE_DEFAULT, RSF_D3D11_USAGE_IMMUTABLE, rsf_d3d11_texture_desc,
    };
    pub use rsf_game_sys::*;
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}

pub mod capture_names;
pub mod capture_pixels;
